using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;using System.Security.AccessControl;using System.Security.Principal;using System.Security.Cryptography;using System.Runtime.InteropServices;

// Immutable history sidecars are NOT commit authority. Only the parent's
// authenticated committed digest, read under its already-held decision lease,
// activates a chain. Callbacks must never reopen that lease.
internal sealed class UsbHidParentCommitLinks:IDisposable {
 internal sealed class View {internal readonly UsbHidAdmissionPolicy.Snapshot Committed;internal readonly UsbHidAdmissionPolicy.Transition Pending;internal View(UsbHidAdmissionPolicy.Snapshot committed,UsbHidAdmissionPolicy.Transition pending){Committed=committed;Pending=pending;}}
 internal sealed class Link {internal readonly UsbHidAdmissionPolicy.Request Request;internal readonly string PnpDigest,PnpBinding;internal Link(UsbHidAdmissionPolicy.Request request,string pnpDigest,string pnpBinding){Request=request;PnpDigest=pnpDigest;PnpBinding=pnpBinding;}}
 internal const int MaximumChain=256,MaximumBytes=65536;
 readonly string directory;readonly Action fence;readonly Func<View> view;readonly Func<string,UsbHidPnpTransaction.State> journal;readonly List<IDisposable> pins=new List<IDisposable>();bool disposed;
 internal static UsbHidParentCommitLinks OpenNative(Action writerFence,Func<View> heldLeaseView,Func<string,UsbHidPnpTransaction.State> authenticatedJournal){return new UsbHidParentCommitLinks(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"SentinelHidAdmission","State"),writerFence,heldLeaseView,authenticatedJournal);}
#if SENTINEL_USB_HID_LINK_PRIVATE
 internal static UsbHidParentCommitLinks OpenPrivate(string nonce,Action writerFence,Func<View> heldLeaseView,Func<string,UsbHidPnpTransaction.State> authenticatedJournal){Hex(nonce,32);return new UsbHidParentCommitLinks(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"SentinelHidParentLinksQualification",nonce),writerFence,heldLeaseView,authenticatedJournal);}
#endif
 UsbHidParentCommitLinks(string location,Action writerFence,Func<View> heldLeaseView,Func<string,UsbHidPnpTransaction.State> authenticatedJournal){if(writerFence==null||heldLeaseView==null||authenticatedJournal==null)throw new ArgumentNullException();directory=location;fence=writerFence;view=heldLeaseView;journal=authenticatedJournal;try{Check();var ancestry=new List<string>();for(var d=new DirectoryInfo(directory);d!=null;d=d.Parent)ancestry.Insert(0,d.FullName);foreach(string path in ancestry){pins.Add(new SentinelPolicyDirectory(path));Security(Directory.GetAccessControl(path),path==directory);}Check();}catch{Dispose();throw;}}
 static InvalidDataException Bad(){return new InvalidDataException("HID parent commit history refused");}void Check(){if(disposed)throw new ObjectDisposedException("UsbHidParentCommitLinks");fence();}
 static bool Trusted(string s){return s=="S-1-5-18"||s=="S-1-5-32-544"||s=="S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464";}
 static void Security(FileSystemSecurity acl,bool leaf){if(!Trusted(acl.GetOwner(typeof(SecurityIdentifier)).Value)||leaf&&!acl.AreAccessRulesProtected)throw Bad();bool sy=false,ba=false;foreach(FileSystemAccessRule r in acl.GetAccessRules(true,true,typeof(SecurityIdentifier))){if(r.AccessControlType!=AccessControlType.Allow)throw Bad();string sid=r.IdentityReference.Value;if(Trusted(sid)){if((r.FileSystemRights&FileSystemRights.FullControl)==FileSystemRights.FullControl){sy|=sid=="S-1-5-18";ba|=sid=="S-1-5-32-544";}continue;}if(!leaf&&(r.PropagationFlags&PropagationFlags.InheritOnly)!=0)continue;if(leaf||(r.FileSystemRights&(FileSystemRights.Delete|FileSystemRights.DeleteSubdirectoriesAndFiles|FileSystemRights.ChangePermissions|FileSystemRights.TakeOwnership))!=0)throw Bad();}if(leaf&&(!sy||!ba))throw Bad();}
 static FileSecurity Acl(){var acl=new FileSecurity();acl.SetOwner(new SecurityIdentifier(WellKnownSidType.BuiltinAdministratorsSid,null));acl.SetAccessRuleProtection(true,false);foreach(var sid in new[]{WellKnownSidType.LocalSystemSid,WellKnownSidType.BuiltinAdministratorsSid})acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid,null),FileSystemRights.FullControl,AccessControlType.Allow));return acl;}
 [StructLayout(LayoutKind.Sequential)]struct Info{internal uint Attributes;internal System.Runtime.InteropServices.ComTypes.FILETIME C,A,W;internal uint Volume,High,Low,Links,IHigh,ILow;}
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetFileInformationByHandle(Microsoft.Win32.SafeHandles.SafeFileHandle h,out Info info);
 static void FileCheck(FileStream f){Security(f.GetAccessControl(),true);Info i;if(!GetFileInformationByHandle(f.SafeFileHandle,out i)||i.Links!=1||(i.Attributes&0x410)!=0)throw Bad();}
 static void Hex(string s,int n){if(s==null||s.Length!=n||s.Any(c=>!Uri.IsHexDigit(c)))throw Bad();}
 static bool Equal(byte[] a,byte[] b){return a!=null&&b!=null&&a.SequenceEqual(b);}
 string PathFor(string digest){Hex(digest,64);return Path.Combine(directory,"hid-parent-"+digest+".bin");}
 byte[] ReadFile(string path){Check();if(!File.Exists(path)){Check();return null;}if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw Bad();using(var f=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){FileCheck(f);if(f.Length<40||f.Length>MaximumBytes)throw Bad();var bytes=new byte[(int)f.Length];int offset=0;while(offset<bytes.Length){int n=f.Read(bytes,offset,bytes.Length-offset);if(n<1)throw Bad();offset+=n;}Check();return bytes;}}
 Link ReadLink(string digest){var bytes=ReadFile(PathFor(digest));if(bytes==null)throw Bad();var link=Decode(bytes);if(link.Request.After.Digest!=digest)throw Bad();return link;}
 internal static byte[] Encode(Link link){if(link==null||link.Request==null)throw Bad();bool pnp=link.Request.Action=="block"||link.Request.Action=="allow";if(pnp){Hex(link.PnpDigest,64);Hex(link.PnpBinding,64);}else if(link.PnpDigest!=null||link.PnpBinding!=null)throw Bad();byte[] request=UsbHidAdmissionPolicy.Encode(link.Request);using(var m=new MemoryStream())using(var w=new BinaryWriter(m,Encoding.ASCII)){w.Write(Encoding.ASCII.GetBytes("SNTHPC01"));w.Write(request.Length);w.Write(request);w.Write(pnp);if(pnp){w.Write(Encoding.ASCII.GetBytes(link.PnpDigest));w.Write(Encoding.ASCII.GetBytes(link.PnpBinding));}w.Flush();if(m.Length>MaximumBytes-32)throw Bad();using(var sha=SHA256.Create())w.Write(sha.ComputeHash(m.ToArray()));w.Flush();return m.ToArray();}}
 internal static Link Decode(byte[] bytes){try{if(bytes==null||bytes.Length<40||bytes.Length>MaximumBytes)throw Bad();byte[] body=bytes.Take(bytes.Length-32).ToArray();using(var sha=SHA256.Create())if(!Equal(sha.ComputeHash(body),bytes.Skip(body.Length).ToArray()))throw Bad();using(var m=new MemoryStream(body))using(var r=new BinaryReader(m,Encoding.ASCII)){if(Encoding.ASCII.GetString(r.ReadBytes(8))!="SNTHPC01")throw Bad();int n=r.ReadInt32();if(n<40||n>UsbHidAdmissionPolicy.MaximumTransitionBytes||n>m.Length-m.Position)throw Bad();var q=UsbHidAdmissionPolicy.DecodeRequest(r.ReadBytes(n));byte has=r.ReadByte();if(has>1)throw Bad();string digest=has==1?Encoding.ASCII.GetString(r.ReadBytes(64)):null,binding=has==1?Encoding.ASCII.GetString(r.ReadBytes(64)):null;if(m.Position!=m.Length)throw Bad();var link=new Link(q,digest,binding);if(!Equal(Encode(link),bytes))throw Bad();return link;}}catch(EndOfStreamException){throw Bad();}catch(ArgumentException){throw Bad();}}
 internal void PublishBeforeCommit(UsbHidAdmissionPolicy.Request request,string pnpDigest,string pnpBinding){Check();var current=view();if(current==null||!UsbHidAdmissionPolicy.Same(current.Committed,request.Before)||current.Pending==null||current.Pending.Request.Digest!=request.Digest||current.Pending.Phase!=UsbHidAdmissionPolicy.Stage.PolicyVerified)throw Bad();if(request.Before.Generation>MaximumChain)throw Bad();var previous=Chain(request.Before);if(previous.Count!=0&&previous[previous.Count-1].Request.After.Digest!=request.Before.Digest)throw Bad();var link=new Link(request,pnpDigest,pnpBinding);if(pnpDigest!=null)ValidatePnp(link,journal(pnpDigest),false);if(request.Action=="deactivate"&&Receipts(previous,true).Length!=0)throw Bad();byte[] bytes=Encode(link);string path=PathFor(request.After.Digest);var existing=ReadFile(path);if(existing!=null){if(!Equal(existing,bytes))throw Bad();return;}string staging=Path.Combine(directory,"hid-parent-write-"+Guid.NewGuid().ToString("N")+".tmp");using(var f=new FileStream(staging,FileMode.CreateNew,FileSystemRights.Read|FileSystemRights.Write,FileShare.None,4096,FileOptions.WriteThrough,Acl())){FileCheck(f);Check();f.Write(bytes,0,bytes.Length);f.Flush(true);}if(!Equal(ReadFile(staging),bytes))throw Bad();Check();File.Move(staging,path);if(!Equal(ReadFile(path),bytes))throw Bad();Check();}
 List<Link> Chain(UsbHidAdmissionPolicy.Snapshot tip){if(tip==null||tip.Generation==0||tip.Generation>MaximumChain+1)throw Bad();var reverse=new List<Link>();var current=tip;while(current.Generation>1){var link=ReadLink(current.Digest);if(!UsbHidAdmissionPolicy.Same(link.Request.After,current))throw Bad();reverse.Add(link);current=link.Request.Before;if(reverse.Count>MaximumChain)throw Bad();}if(current.Active||current.ExternalApprovals.Length!=0)throw Bad();reverse.Reverse();return reverse;}
 static void ValidatePnp(Link link,UsbHidPnpTransaction.State state,bool committed){if(state==null||state.Digest!=link.PnpDigest||state.Binding!=link.PnpBinding||state.Action!=link.Request.Action||state.Phase!=(committed?"Committed pending physical verification":"Applied pending physical verification")||state.Revision<1)throw Bad();var target=new HashSet<string>(link.Request.Targets,StringComparer.OrdinalIgnoreCase);if(target.Count!=state.Entries.Length)throw Bad();foreach(var e in state.Entries)if(e==null||e.Plan==null||!target.Remove(e.Plan.Instance)||e.Plan.Topology!=link.Request.TopologyHash||e.Restored)throw Bad();if(target.Count!=0)throw Bad();var lines=state.Entries.Select(e=>e.Plan.Instance.ToUpperInvariant()+"\n"+e.Plan.Topology+"\n"+e.Plan.Tree+"\n"+(e.Plan.RecoveryConnector??"<missing>")+"\n"+(e.Plan.RecoveryTree??"<missing>")).OrderBy(x=>x,StringComparer.Ordinal);using(var sha=SHA256.Create())if(BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(state.Action+"\n"+string.Join("\n--\n",lines.ToArray())))).Replace("-","")!=state.Binding)throw Bad();}
 UsbHidCommittedDisableLedger.Receipt[] Receipts(List<Link> chain,bool requireCommitted){var result=new Dictionary<string,UsbHidCommittedDisableLedger.Receipt>(StringComparer.OrdinalIgnoreCase);foreach(var link in chain){var q=link.Request;if(q.Action=="allow"){foreach(string target in q.Targets)result.Remove(target);continue;}if(q.Action!="block")continue;var pnp=journal(link.PnpDigest);ValidatePnp(link,pnp,requireCommitted);foreach(var e in pnp.Entries){result.Remove(e.Plan.Instance);if(e.Intent&&e.Observed&&!e.Restored&&e.BeforeDisableable&&UsbHidPnpTransaction.CanDisable(e.BeforeStatus,e.BeforeProblem)&&(e.Outcome=="Pending verification"||e.Outcome=="Blocked")&&!string.IsNullOrEmpty(e.AfterTree))result.Add(e.Plan.Instance,new UsbHidCommittedDisableLedger.Receipt(e.Plan.Instance,e.AfterTree,link.PnpDigest,link.PnpBinding,q.After.Digest,checked((long)q.After.Generation)));}}return result.Values.OrderBy(r=>r.Instance,StringComparer.Ordinal).ToArray();}
 internal UsbHidCommittedDisableLedger.IAuthenticatedSource Source(string ownedPendingDigest=null){return new AuthenticatedSource(this,ownedPendingDigest);}
 sealed class AuthenticatedSource:UsbHidCommittedDisableLedger.IAuthenticatedSource {
  readonly UsbHidParentCommitLinks owner;readonly string pendingDigest;internal AuthenticatedSource(UsbHidParentCommitLinks links,string allowedPending){owner=links;pendingDigest=allowedPending;}
  View Current(){owner.Check();var v=owner.view();if(v==null||v.Committed==null)throw Bad();if(v.Pending!=null&&(pendingDigest==null||v.Pending.Request.Digest!=pendingDigest||!UsbHidAdmissionPolicy.Same(v.Committed,v.Pending.Request.Before)||v.Pending.Request.Action!="allow"||v.Pending.Phase==UsbHidAdmissionPolicy.Stage.RecoveryClaimed||v.Pending.Phase>=UsbHidAdmissionPolicy.Stage.Committed))throw Bad();owner.Check();return v;}
  public UsbHidCommittedDisableLedger.PolicySnapshot ReadCurrentCommittedPolicy(){var v=Current();var receipts=owner.Receipts(owner.Chain(v.Committed),true);var after=Current();if(!UsbHidAdmissionPolicy.Same(v.Committed,after.Committed))throw Bad();return new UsbHidCommittedDisableLedger.PolicySnapshot(checked((long)v.Committed.Generation),v.Committed.Digest,false,receipts);}
  public UsbHidCommittedDisableLedger.ParentCommit ReadCommittedParentGeneration(long generation){var v=Current();foreach(var link in owner.Chain(v.Committed))if(checked((long)link.Request.After.Generation)==generation){var q=link.Request;return new UsbHidCommittedDisableLedger.ParentCommit(generation,q.After.Digest,q.Action,link.PnpDigest,link.PnpBinding,q.Targets);}throw Bad();}
  public UsbHidPnpTransaction.State ReadAuthenticatedPnpJournal(string digest){Current();var result=owner.journal(digest);owner.Check();return result;}
 }
 // Close the durable-parent/PnP-Applied crash window before retiring recovery.
 // The supplied commit callback is the real journal transaction Commit under
 // this SAME held parent fence. It must not perform a device transition.
 internal void ReconcileCommitted(UsbHidAdmissionPolicy.Request request,Func<string,string,UsbHidSetupApi.Plan[],UsbHidPnpTransaction.State> commitPnp){if(request==null||commitPnp==null)throw new ArgumentNullException();Check();var v=view();if(v==null||!UsbHidAdmissionPolicy.Same(v.Committed,request.After)||v.Pending==null||v.Pending.Request.Digest!=request.Digest)throw Bad();var link=ReadLink(request.After.Digest);if(link.Request.Digest!=request.Digest)throw Bad();if(link.PnpDigest==null)return;var state=journal(link.PnpDigest);if(state!=null&&state.Phase=="Committed pending physical verification"){ValidatePnp(link,state,true);return;}ValidatePnp(link,state,false);commitPnp(link.PnpDigest,request.Action,Array.ConvertAll(state.Entries,e=>e.Plan));Check();ValidatePnp(link,journal(link.PnpDigest),true);var final=view();if(final==null||!UsbHidAdmissionPolicy.Same(final.Committed,request.After)||final.Pending==null||final.Pending.Request.Digest!=request.Digest)throw Bad();}
 public void Dispose(){if(disposed)return;disposed=true;for(int i=pins.Count-1;i>=0;i--)pins[i].Dispose();pins.Clear();}
}
